// The contract harness for the worked example: no network, fixtures only.
// A contributor copies this file and replaces the fixture with their board's
// captured response — never with output generated by the code under test.
import { expect, test } from "bun:test";
import { arbeitnowProvider, mapJob, filterJobs } from "../src/helpers.js";

const raw = {
  slug: "engineer-1",
  title: "Backend Engineer",
  company_name: "Example Co",
  location: "Bengaluru",
  remote: false,
  url: "https://example.test/jobs/engineer-1",
  created_at: Math.floor(Date.parse("2026-11-20T00:00:00Z") / 1000),
  tags: ["python", "backend"],
  description: "<p>Build Python services</p>",
};

test("the SDK maps the board's raw fields into the neutral row", () => {
  const row = mapJob(raw);
  expect(row).not.toBeNull();
  expect(row!.id).toBe("engineer-1");
  expect(row!.title).toBe("Backend Engineer");
  expect(row!.location).toBe("Bengaluru");
  expect(row!.date).toBe("2026-11-20");
  expect(row!.url).toBe("https://example.test/jobs/engineer-1");
});

test("the query filter is client-side, not a network call", () => {
  const row = mapJob(raw)!;
  // filterArbeitnow matches against title + company, so a title word hits
  // and an unrelated word misses — entirely in memory, no fetch.
  expect(filterJobs([row], { query: "backend" })).toHaveLength(1);
  expect(filterJobs([row], { query: "cobol" })).toHaveLength(0);
});

test("the provider declares the shared contract", () => {
  expect(arbeitnowProvider.id).toBe("arbeitnow");
  expect(arbeitnowProvider.seedUrls[0].startsWith("https://")).toBe(true);
  expect(arbeitnowProvider.version).toMatch(/^\d+\.\d+\.\d+$/);
});
